"""
Resúmenes editoriales para las series Seinen y grandes clásicos del catálogo de Akibara.
Longitud objetivo: 120-170 palabras en 3 párrafos limpios.
"""

SERIES_SEINEN_CLASSICS = {
    "20th-century-boys": """<p><strong>20th Century Boys</strong> (<em>Nijusseiki Shōnen</em>), la aclamada obra maestra de <strong>Naoki Urasawa</strong> (autor de <em>Monster</em> y <em>Pluto</em>), es uno de los mayores thrillers de conspiración, memoria y misterio del cómic contemporáneo. En 1969, un grupo de niños escribe en su base secreta el «Libro de las Profecías», inventando un juego donde una malvada secta intenta destruir el mundo en el año 2000. Tres décadas más tarde, una ola de atentados y una siniestra figura enmascarada apodada «Amigo» comienzan a hacer realidad cada una de aquellas predicciones infantiles.</p>
<p>Con una deslumbrante narrativa no lineal y saltos temporales magistrales, la historia se consagra en la prestigiosa <strong>edición Kanzenban de 11 tomos dobles</strong> más el desenlace especial <em>21st Century Boys</em>, con formato ampliado y páginas a color.</p>
<p>Encuentra la colección completa de <strong>20th Century Boys</strong> en su edición oficial de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "maximum-berserk": """<p><strong>Maximum Berserk</strong> recopila en gran formato la monumental epopeya de fantasía oscura medieval creada por el recordado maestro <strong>Kentaro Miura</strong> para la revista <em>Young Animal</em> de Hakusensha. La historia narra el tormentoso destino de <strong>Guts</strong>, el «Espadachín Negro», un solitario guerrero marcado por un estigma demoníaco que atrae a espíritus malignos sin tregua. Blandiendo su descomunal espada Matadragones, Guts libra una guerra visceral contra apóstoles infernales y su antiguo hermano de armas, <strong>Griffith</strong>, líder de la legendaria Banda del Halcón.</p>
<p>La edición <strong>Maximum</strong> destaca por su impactante tamaño ampliado (B5) y papel de alta calidad, permitiendo apreciar con toda su fuerza el arte detallista en tinta china de Miura.</p>
<p>Consigue la colección de <strong>Maximum Berserk en español</strong> editada por <strong>Panini Comics España</strong> en <strong>Akibara</strong>, con stock protegido y despacho seguro a todo Chile.</p>""",

    "vinland-saga": """<p><strong>Vinland Saga</strong> (<em>ヴィンランド・サガ</em>), la monumental epopeya vikinga creada por <strong>Makoto Yukimura</strong> en <em>Monthly Afternoon</em> de Kodansha, es una de las mayores cumbres narrativas sobre la venganza, el honor y la redención. La trama sigue al joven guerrero <strong>Thorfinn</strong>, quien jura matar en un duelo limpio al mercenario <strong>Askeladd</strong>, asesino de su padre Thors. Atrapado en medio de sangrientas batallas por la corona de Inglaterra, Thorfinn atravesará la brutalidad de la guerra hasta buscar una tierra legendaria sin cadenas ni esclavitud: Vinland.</p>
<p>Para continuar la historia tras la magistral segunda temporada del anime (MAPPA), la lectura en el manga se retoma directamente a partir del <strong>Tomo 09</strong> en adelante.</p>
<p>En <strong>Akibara</strong> dispones de la colección oficial de <strong>Vinland Saga en español</strong> por <strong>Planeta Cómic</strong>, con despacho rápido a todo el territorio de Chile.</p>""",

    "monster": """<p><strong>Monster</strong>, la inolvidable obra cumbre del suspense psicológico creada por <strong>Naoki Urasawa</strong> en <em>Big Comic Original</em> de Shogakukan, es reconocida unánimemente como uno de los mejores thrillers de la historia. En la Alemania de la Guerra Fría, el brillante neurocirujano japonés <strong>Kenzō Tenma</strong> decide salvar la vida de un niño herido de bala, Johan Liebheart, en lugar de operar al alcalde de Düsseldorf. Años más tarde, Tenma descubre con horror que aquel niño ha crecido para convertirse en un carismático monstruo psicópata desprovisto de empatía, iniciando una cacería implacable por Europa Central.</p>
<p>Concluida en <strong>9 tomos de lujo</strong> en formato Kanzenban, la obra destaca por su realismo histórico, dilemas éticos y ritmo cinematográfico perfecto.</p>
<p>Compra la colección completa de <strong>Monster en español</strong> editada por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos a todo Chile.</p>""",

    "pluto": """<p><strong>Pluto</strong>, la brillante reinterpretación del legendario arco «El mayor robot sobre la Tierra» de <em>Astro Boy</em> (Osamu Tezuka) realizada por <strong>Naoki Urasawa</strong> y Takashi Nagasaki, es una conmovedora reflexión sobre la inteligencia artificial, el odio y el duelo. El inspector robot <strong>Gesicht</strong> de la Europol investiga una serie de asesinatos en serie que tienen como víctimas a los siete robots más avanzados y poderosos del mundo y a sus defensores humanos, dejando en cada escena siniestros cuernos como firma macabra.</p>
<p>La serie completa está recopilada en <strong>8 tomos</strong> de suspense impecable, aclamada internacionalmente y adaptada al anime por Netflix y Studio M2.</p>
<p>Consigue la serie de <strong>Pluto en español</strong> en su edición de <strong>Planeta Cómic</strong> en <strong>Akibara</strong>, con despacho seguro a todo Chile.</p>""",

    "vagabond": """<p><strong>Vagabond</strong> (<em>バガボンド</em>), la deslumbrante obra maestra de <strong>Takehiko Inoue</strong> basada en la novela <em>Musashi</em> de Eiji Yoshikawa, es la cúspide artística del manga histórico de samuráis. Tras sobrevivir a la sangrienta batalla de Sekigahara en 1600, el joven e indómito Shinmen Takezo renace bajo el nombre de <strong>Miyamoto Musashi</strong>, jurando convertirse en el espadachín invencible bajo el cielo. A través de combates a muerte y una profunda búsqueda espiritual, Musashi comprenderá el verdadero peso de quitar una vida y la naturaleza del filo de la espada.</p>
<p>El virtuosismo visual de Inoue, dibujado enteramente a pincel y tinta china, convierte cada página en una auténtica obra de arte para coleccionistas.</p>
<p>Adquiere la colección oficial de <strong>Vagabond en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos reforzados a todo Chile.</p>""",

    "homunculus": """<p><strong>Homunculus</strong> (<em>ホムンクルス</em>), la perturbadora obra de culto del thriller psicológico creada por <strong>Hideo Yamamoto</strong> (autor de <em>Ichi the Killer</em>) en <em>Big Comic Spirits</em>, explora las profundidades más oscuras del subconsciente. <strong>Susumu Nakoshi</strong>, un antiguo ejecutivo de finanzas que vive como indigente dentro de su automóvil entre un parque y un hotel de lujo, acepta someterse a una trepanación craneal a cambio de dinero. Al despertar tras la cirugía, Nakoshi descubre que al mirar con su ojo izquierdo puede ver los traumas y distorsiones reprimidas de los seres humanos materializados como grotescos homúnculos.</p>
<p>La serie completa se encuentra recopilada en <strong>15 tomos</strong> de fascinación psicológica, tensión y surrealismo absoluto.</p>
<p>Consigue <strong>Homunculus en español</strong> en su edición oficial de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "dorohedoro": """<p><strong>Dorohedoro</strong> (<em>ドロヘドロ</em>), la inclasificable y visceral obra de culto de <strong>Q Hayashida</strong> en <em>Monthly Ikki</em> de Shogakukan, combina con maestría fantasía oscura, humor negro, cyberpunk sucio y violencia desatada. En la decadente ciudad de «El Hoyo», los hechiceros utilizan a los humanos como conejillos de indias para practicar su magia negra. <strong>Caiman</strong>, un hombre con cabeza de reptil y amnesia severa, se dedica a cazar hechiceros junto a su inseparable compañera Nikaido, introduciendo sus cabezas en sus fauces para que el misterioso hombre que habita en su garganta determine quién fue el culpable de su maldición.</p>
<p>Para continuar la historia tras la primera temporada del anime producido por <strong>MAPPA</strong>, la lectura en el manga se retoma a partir del <strong>Tomo 07</strong>.</p>
<p>Colecciona <strong>Dorohedoro en español</strong> en la edición oficial de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos protegidos a todo Chile.</p>""",

    "gantz-deluxe-edition": """<p><strong>Gantz</strong> (<em>ガンツ</em>), el salvaje clásico de ciencia ficción y acción gore creado por <strong>Hiroya Oku</strong> en <em>Weekly Young Jump</em> de Shueisha, marcó una era por su narrativa extrema y combates sin censura. Los estudiantes <strong>Kei Kurono</strong> y Masaru Kato mueren atropellados en el metro tras salvar a un vagabundo, pero despiertan en un departamento de Tokio frente a una misteriosa esfera negra parlante llamada Gantz. Obligados a enfundarse trajes especiales de combate y empuñar armas futuristas, deberán cazar alienígenas clandestinos en misiones nocturnas para sumar 100 puntos y comprar su libertad.</p>
<p>La <strong>edición Deluxe</strong> recopila esta inolvidable saga con formato ampliado, mayor gramaje y páginas a color.</p>
<p>Compra <strong>Gantz Deluxe en español</strong> editado por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho seguro a todo Chile.</p>""",

    "hellsing-edicion-inmortal": """<p><strong>Hellsing</strong>, la icónica obra gótica de acción sobrenatural y vampiros creada por <strong>Kōta Hirano</strong> en <em>Young King OURs</em> de Shōnen Gahōsha, es uno de los mayores exponentes del dark fantasy estilizado. La Organización Hellsing, liderada por Sir Integra Fairbrook Wingates Hellsing, defiende al Imperio Británico del azote de no-muertos y ghouls utilizando su arma más letal y temible: <strong>Alucard</strong>, el rey de los vampiros primigenio, quien junto a su aprendiz Seras Victoria combate contra el Vaticano y la sanguinaria facción nazi Millennium.</p>
<p>La <strong>Edición Inmortal</strong> presenta la serie en tomos de gran formato con portadas especiales, páginas satinadas a color y reproducción de arte de alta definición.</p>
<p>Adquiere <strong>Hellsing Edición Inmortal en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "akira": """<p><strong>Akira</strong> (<em>アキラ</em>), la inmortal obra maestra de ciencia ficción ciberpunk creada por <strong>Katsuhiro Otomo</strong> para la revista <em>Young Magazine</em> de Kodansha, revolucionó el noveno arte y el cómic mundial. En el año 2019, tres décadas después de que una explosión nuclear desatara la Tercera Guerra Mundial y destruyera Tokio, la caótica megalópolis de <strong>Neo-Tokio</strong> está sumida en la decadencia, protestas y guerra de bandas motorizadas. <strong>Kaneda</strong>, líder de una pandilla de adolescentes, ve cómo su mejor amigo <strong>Tetsuo</strong> sufre un accidente y despierta descomunales poderes telequinéticos ligados a un proyecto militar secreto: el misterio de Akira.</p>
<p>Publicada en <strong>6 monumentales tomos</strong> de gran formato, es una lectura imprescindible de valor histórico e influencia artística inagotable.</p>
<p>Compra la colección oficial de <strong>Akira en español</strong> por <strong>Ovni Press</strong> en <strong>Akibara</strong>, con despacho reforzado a todo Chile.</p>""",

    "oyasumi-punpun": """<p><strong>Oyasumi Punpun</strong> (<em>Buenas noches, Punpun</em>), la desgarradora obra cumbre de <strong>Inio Asano</strong> en <em>Weekly Young Sunday</em> y <em>Big Comic Spirits</em> de Shogakukan, es uno de los retratos más lúcidos y dolorosos sobre la pérdida de la inocencia, la soledad y la salud mental en el manga. La historia sigue la vida de <strong>Punpun Onodera</strong>, un niño dibujado deliberadamente como un caricaturesco pajarito blanco, desde sus días de primaria hasta la adultez temprana, mientras lidia con una familia disfuncional, la violencia doméstica y su obsesivo amor platónico por <strong>Aiko Tanaka</strong>.</p>
<p>Completada en <strong>13 tomos</strong> de maestría visual hiperrealista y densidad emocional única, es un hito de la narrativa contemporánea.</p>
<p>Encuentra la colección de <strong>Oyasumi Punpun en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "golden-kamuy": """<p><strong>Golden Kamuy</strong> (<em>ゴールデンカムイ</em>), la galardonada obra maestra de <strong>Satoru Noda</strong> en <em>Weekly Young Jump</em> de Shueisha (ganadora del Premio Manga Taishō y del Premio Cultural Tezuka Osamu), combina acción militar histórica, folclore indígena y humor gastronómico. En el gélido Hokkaido tras la guerra ruso-japonesa de 1905, el veterano apodado <strong>«Sugimoto el Inmortal»</strong> busca oro para ayudar a la viuda de un camarada. Al enterarse de un legendario tesoro de oro ainu oculto cuya pista fue tatuada en la piel de 24 convictos prófugos, formará equipo con la joven cazadora ainu <strong>Asirpa</strong>.</p>
<p>Para continuar la historia tras la cuarta temporada del anime producido por <strong>Brain's Base</strong>, la lectura se retoma desde el <strong>Tomo 21</strong> en adelante.</p>
<p>Adquiere <strong>Golden Kamuy en español</strong> editado por <strong>Panini Manga Argentina</strong> en <strong>Akibara</strong>, con despacho a todo Chile.</p>""",

    "kingdom": """<p><strong>Kingdom</strong> (<em>キングダム</em>), la colosal epopeya histórica de <strong>Yasuhisa Hara</strong> en <em>Weekly Young Jump</em> con más de 100 millones de copias vendidas, es una de las mayores cumbres del manga militar y táctico. Ambientada en la sangrienta era de los Reinos Combatientes de la antigua China, el joven esclavo huérfano de guerra <strong>Shin</strong> entrena a diario para convertirse en el Gran General bajo los cielos. Tras la trágica muerte de su amigo Piao, Shin se alía con el joven rey <strong>Ei Sei</strong> (el futuro emperador Qin Shi Huang), combatiendo en batallas multitudinarias para unificar toda China bajo una sola bandera.</p>
<p>Con batallas estratégicas épicas y una progresión arrolladora, es una lectura indispensable para los amantes de la historia y el combate épico.</p>
<p>Encuentra los tomos de <strong>Kingdom en español</strong> editados por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos a todo Chile.</p>""",

    "beastars": """<p><strong>Beastars</strong> (<em>ビースターズ</em>), la multipremiada obra creada por <strong>Paru Itagaki</strong> para <em>Weekly Shōnen Champion</em> de Akita Shoten (ganadora del Premio Manga Taishō y Premio Tezuka), es una aguda parábola social ambientada en un mundo de animales antropomórficos divididos entre carnívoros y herbívoros. En la Academia Cherryton, la misteriosa devoración del alpaca Tem desata la desconfianza general. <strong>Legoshi</strong>, un lobo gris intimidante pero sumamente tímido y reflexivo, lucha contra sus propios instintos carnívoros al enamorarse de <strong>Haru</strong>, una coneja enana blanca de personalidad audaz.</p>
<p>Para continuar la trama tras las dos primeras temporadas del anime producido por <strong>Studio Orange</strong> en Netflix, la lectura se retoma desde el <strong>Tomo 12</strong>.</p>
<p>Colecciona <strong>Beastars en español</strong> (22 tomos completos) por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho seguro a todo Chile.</p>""",

    "banana-fish": """<p><strong>Banana Fish</strong>, el legendario drama noir creado por <strong>Akimi Yoshida</strong> en <em>Bessatsu Shōjo Comic</em> de Shogakukan, es uno de los mayores clásicos del thriller de mafia, espionaje y acción psicológica. En los bajos fondos de la Nueva York de los años ochenta, <strong>Ash Lynx</strong>, un joven líder de pandillas de letal puntería e inteligencia prodigiosa, intenta desentrañar el significado de las enigmáticas palabras «Banana Fish» que balbucea su hermano traumatizado por la guerra. Su destino cambia al conocer a <strong>Eiji Okumura</strong>, un noble asistente de fotógrafo japonés que se convertirá en su mayor luz y debilidad.</p>
<p>Publicada en una magnífica <strong>edición de 10 tomos dobles</strong> con el epílogo especial <em>Garden of Light</em>, es una historia desgarradora e inolvidable.</p>
<p>Encuentra <strong>Banana Fish en español</strong> en su edición de <strong>Panini Manga Argentina</strong> en <strong>Akibara</strong>, con envío a todo Chile.</p>""",

    "blue-period": """<p><strong>Blue Period</strong> (<em>ブルーピリオド</em>), la aclamada obra creada por <strong>Tsubasa Yamaguchi</strong> en <em>Monthly Afternoon</em> de Kodansha (ganadora del Manga Taishō y del Premio Kodansha Manga), es un viaje vocacional conmovedor sobre la pasión por el arte. <strong>Yatora Yaguchi</strong> es un estudiante ejemplar y popular que siente un profundo vacío interior. Todo cambia cuando contempla accidentalmente una pintura al óleo de una compañera en el club de arte, despertando en él una necesidad visceral de expresarse y aspirar al examen de ingreso de la Universidad de las Artes de Tokio (Geidai), la escuela de arte más exigente de Japón.</p>
<p>Para continuar la historia tras la primera temporada del anime producido por <strong>Seven Arcs</strong> en Netflix, la lectura se retoma a partir del <strong>Tomo 07</strong>.</p>
<p>Adquiere <strong>Blue Period en español</strong> por <strong>Panini Manga Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "made-in-abyss": """<p><strong>Made In Abyss</strong> (<em>メイドインアビス</em>), la fascinante fantasía oscura creada por <strong>Akihito Tsukushi</strong> en <em>Web Comic Gamma</em> de Takeshobo, destaca por el impresionante contraste entre su diseño de personajes inocente y el horror biológico más sobrecogedor. En una isla remota se encuentra el «Abismo», una descomunal fosa subterránea repleta de reliquias de una civilización perdida y monstruosas criaturas. La pequeña huérfana <strong>Riko</strong>, decidida a descender hasta el fondo para reencontrarse con su legendaria madre Lyza, emprende el viaje sin retorno junto a <strong>Reg</strong>, un niño robot amnésico.</p>
<p>Para continuar tras la segunda temporada del anime (<em>La ciudad dorada del sol abrasador</em>), la lectura se retoma desde el <strong>Tomo 11</strong>.</p>
<p>Consigue <strong>Made In Abyss en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho protegido a todo Chile.</p>""",

    "mob-psycho-100": """<p><strong>Mob Psycho 100</strong> (<em>モブサイコ100</em>), la célebre obra creada por <strong>ONE</strong> (autor de <em>One-Punch Man</em>) en <em>Ura Sunday</em> de Shogakukan, es una brillante combinación de poderes psíquicos descomunales, comedia y madurez emocional. <strong>Shigeo Kageyama («Mob»)</strong> es un estudiante de secundaria con habilidades telequinéticas de nivel catastrófico, pero cuyo mayor deseo es llevar una vida ordinaria, conquistar a la chica que le gusta y controlar sus emociones para no estallar al llegar al 100%. Junto a su carismático maestro y falso exorcista, <strong>Reigen Arataka</strong>, Mob aprenderá que los poderes no lo hacen superior a nadie.</p>
<p>Concluida en <strong>16 tomos</strong> de ritmo trepidante, la serie ofrece uno de los mejores desarrollos de personajes del manga moderno.</p>
<p>Encuentra la colección oficial de <strong>Mob Psycho 100 en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos a todo Chile.</p>""",

    "parasyte": """<p><strong>Parasyte</strong> (<em>Kiseijuu</em> / <em>寄生獣</em>), el clásico indispensable del terror biológico y ciencia ficción creado por <strong>Hitoshi Iwaaki</strong> en <em>Monthly Afternoon</em> de Kodansha, es una de las obras más influyentes de la historieta japonesa. De la noche a la mañana, diminutas esporas alienígenas caen sobre la Tierra y parasitan los cerebros de los humanos, convirtiéndolos en voraces monstruos carnívoros. El joven <strong>Shinichi Izumi</strong> logra evitar que su parásito llegue a su cabeza, quedando este atrapado en su mano derecha bajo el nombre de <strong>Migi</strong>, desatando una frágil alianza simbiótica para sobrevivir.</p>
<p>La serie completa está recopilada en <strong>8 tomos</strong> llenos de tensión psicológica, batallas letales y profundos dilemas sobre la naturaleza humana.</p>
<p>Compra <strong>Parasyte en español</strong> en su edición oficial de <strong>Planeta Cómic</strong> en <strong>Akibara</strong>, con despacho seguro a todo Chile.</p>""",

    "uzumaki": """<p><strong>Uzumaki</strong> (<em>うずまき</em>), la indiscutible obra cumbre del maestro del horror cósmico <strong>Junji Ito</strong> serializada en <em>Big Comic Spirits</em> de Shogakukan, es uno de los mangas de terror más perturbadores y leídos del mundo. En la aislada y neblinosa ciudad costera de Kurouzu-cho, una extraña maldición no encarnada en un monstruo, sino en una forma geométrica abstracta —la espiral—, comienza a infectar la mente y los cuerpos de sus habitantes, distorsionando la realidad física hacia el delirio, la mutación y la locura colectiva.</p>
<p>Narrada a través de los ojos de los jóvenes <strong>Kirie Goshima</strong> y Shuichi Saito, la obra cautiva por su imaginería visual grotesca e hipnótica.</p>
<p>Adquiere <strong>Uzumaki en español</strong> en su edición de lujo de <strong>Planeta Cómic</strong> en <strong>Akibara</strong>, con despacho rápido a todo el territorio chileno.</p>""",

    "zom-100": """<p><strong>Zom 100: Bucket List of the Dead</strong> (<em>Zombie 100: Zombie ni Naru Made ni Shitai 100 no Koto</em>), con guion de <strong>Haro Aso</strong> (creador de <em>Alice in Borderland</em>) y arte de <strong>Kotaro Takata</strong> en <em>Sunday GX</em> de Shogakukan, reinventó el género zombi con desbordante optimismo y humor vital. <strong>Akira Tendo</strong> lleva tres años atrapado en una empresa explotadora donde vive alienado, sin dormir y sin ganas de vivir. Cuando un repentino apocalipsis zombi arrasa Tokio, Akira no siente terror, sino una felicidad absoluta: ¡por fin no tiene que ir a trabajar! Decidido a exprimir la vida, redactará una lista con 100 cosas que hacer antes de ser devorado.</p>
<p>Para continuar tras los 12 episodios del anime producido por <strong>BUG FILMS</strong>, la lectura se retoma desde el <strong>Tomo 04</strong> en adelante.</p>
<p>Encuentra <strong>Zom 100 en español</strong> por <strong>Panini Manga Argentina</strong> en <strong>Akibara</strong>, con envíos rápidos a todo Chile.</p>""",

    "rurouni-kenshin": """<p><strong>Rurouni Kenshin: El guerrero samurái</strong> (<em>るろうに剣心</em>), el inmortal clásico histórico de <strong>Nobuhiro Watsuki</strong> en <em>Weekly Shōnen Jump</em> con más de 72 millones de copias vendidas, es una de las mayores epopeyas sobre el honor y la expiación. En el Japón de la era Meiji (1878), <strong>Kenshin Himura</strong>, el legendario asesino conocido como «Hitokiri Battōsai» durante la caída del shogunato, recorre el país como un vagabundo portando una espada de filo invertido (sakabatō), jurando no volver a matar jamás y proteger a los débiles junto a Kaoru Kamiya en el dojo Kamiya Kasshin Ryu.</p>
<p>Con batallas legendarias como el enfrentamiento contra Makoto Shishio y el arco del castigo humano (Jinchū), es un hito de la narrativa gráfica japonesa.</p>
<p>Colecciona <strong>Rurouni Kenshin en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "tokyo-ghoul": """<p><strong>Tokyo Ghoul</strong> (<em>東京喰種</em>), el sobrecogedor dark fantasy creado por <strong>Sui Ishida</strong> en <em>Weekly Young Jump</em> de Shueisha con más de 47 millones de copias, redefinió la fantasía urbana contemporánea. En las sombras de Tokio habitan los «Ghouls», seres de apariencia humana que solo pueden alimentarse de carne humana y café. El tímido estudiante universitario <strong>Ken Kaneki</strong> sobrevive al ataque de un ghoul tras un trasplante de órganos de emergencia, despertando convertido en un híbrido mitad humano y mitad ghoul, debiendo esconderse entre el café Anteiku y la implacable Comisión de Contramedidas Ghoul (CCG).</p>
<p>Completada en <strong>14 tomos</strong> de arte oscuro y evolución psicológica implacable, la serie supera con creces la adaptación animada de Studio Pierrot.</p>
<p>Consigue <strong>Tokyo Ghoul en español</strong> en su edición de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho seguro a todo Chile.</p>""",

    "tokyo-ghoul-re": """<p><strong>Tokyo Ghoul:re</strong> (<em>東京喰種:re</em>), la esperada continuación directa de la saga creada por <strong>Sui Ishida</strong> en <em>Weekly Young Jump</em>, traslada el conflicto al otro lado de la trinchera. Dos años después del devastador asalto al Anteiku, la CCG crea el escuadrón especial «Quinx», investigadores humanos a los que se les han implantado quirúrgicamente células ghoul para combatir con sus mismas armas. Al frente del escuadrón se encuentra <strong>Haise Sasaki</strong>, un talentoso y compasivo mentor que arrastra una severa amnesia que oculta su verdadera y trágica identidad como Ken Kaneki.</p>
<p>Concluida en <strong>16 tomos</strong> repletos de batallas a gran escala, revelaciones genealógicas y el desenlace de la coexistencia entre humanos y ghouls.</p>
<p>Encuentra <strong>Tokyo Ghoul:re en español</strong> editado por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos rápidos a todo Chile.</p>""",

    "real": """<p><strong>REAL</strong> (<em>リアル</em>), la conmovedora e intensa obra de <strong>Takehiko Inoue</strong> (autor de <em>Slam Dunk</em> y <em>Vagabond</em>) en <em>Weekly Young Jump</em>, aborda con maestría y respeto el mundo del baloncesto en silla de ruedas y la superación humana. La trama entrelaza las vidas de tres jóvenes golpeados por la adversidad: Tomomi Nomiya, un desertor escolar con remordimientos tras causar un accidente de tránsito; Kiyoharu Togawa, un velocista con una pierna amputada debido a un osteosarcoma; y Hisanobu Takahashi, el arrogante capitán del equipo de básquetbol que queda parapléjico tras un choque.</p>
<p>Inoue despliega un dibujo realista superlativo y una profunda carga emocional sobre la dignidad, la resiliencia y el deseo de volver a ponerse de pie.</p>
<p>Adquiere los tomos oficiales de <strong>REAL en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho seguro a todo Chile.</p>""",

    "solanin": """<p><strong>Solanin</strong> (<em>ソラニン</em>), la aclamada obra intimista creada por <strong>Inio Asano</strong> para <em>Weekly Young Sunday</em> de Shogakukan, es un retrato generacional indispensable sobre el paso a la adultez, la incertidumbre laboral y el duelo. <strong>Meiko Inoue</strong> y su novio <strong>Naruo Taneda</strong> son dos jóvenes graduados universitarios en Tokio que lidian con la monotonía de los trabajos de oficina y el miedo al futuro. Cuando Meiko renuncia a su empleo y alienta a Taneda a apostarlo todo por su banda de indie rock, una tragedia inesperada obligará a Meiko a tomar la guitarra para encontrar su propio camino.</p>
<p>Publicada en formato integral de tomo doble, es una lectura emotiva, cercana y de culto dentro del cómic contemporáneo.</p>
<p>Encuentra <strong>Solanin en español</strong> en su edición de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "choujin-x": """<p><strong>Choujin X</strong> (<em>超人X</em>), la nueva gran obra de fantasía oscura y acción creada por <strong>Sui Ishida</strong> (autor de <em>Tokyo Ghoul</em>) para <em>Tonari no Young Jump</em>, explora un mundo hostil habitado por seres con poderes mutantes llamados «Choujin». En la prefectura de Yamato, los amigos de secundaria <strong>Tokio Kurohara</strong> y el talentoso Azuma Higashi se ven acorralados por un pandillero transformado en bestia, viéndose forzados a inyectarse una jeringa misteriosa que convierte a Tokio en un Choujin Buitre, debiendo aprender a controlar su condición en la academia Yamamori.</p>
<p>Ishida despliega su característico estilo vanguardista y libre, fusionando combates espectaculares, transformaciones monstruosas y drama de madurez.</p>
<p>Compra <strong>Choujin X en español</strong> en la edición de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos a todo Chile.</p>""",

    "dai-dark": """<p><strong>Dai Dark</strong> (<em>大ダーク</em>), la desternillante y siniestra odisea espacial creada por <strong>Q Hayashida</strong> (autora de <em>Dorohedoro</em>) para <em>Monthly Shōnen Sunday</em> (Gessan) de Shogakukan, combina fantasía gótica espacial, ciencia ficción retro y humor absurdo. <strong>Zaha Sanko</strong> es un adolescente de catorce años que carga con una tremenda maldición: se dice que quien posea sus huesos podrá cumplir cualquier deseo y convertirse en el amo supremo del universo. Acompañado por su inseparable amigo esqueleto Avakian, Sanko viaja por el cosmos desmembrando a cazarrecompensas con su hacha mágica.</p>
<p>Con un diseño de criaturas macabro y páginas repletas de detalles delirantes, es una lectura única en su género.</p>
<p>Colecciona <strong>Dai Dark en español</strong> en la edición oficial de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho seguro a todo Chile.</p>""",

    "centuria": """<p><strong>Centuria</strong> (<em>センチュリア</em>), la impactante revelación de fantasía oscura creada por <strong>Tohru Kuramori</strong> (antiguo asistente destacado de Tatsuki Fujimoto) para <em>Shōnen Jump+</em>, cautivó a los lectores desde su debut por su tono visceral y trágico. La historia sigue a <strong>Julian</strong>, un esclavo que viaja escondido en las bodegas de un barco para huir hacia la libertad. Cuando una misteriosa entidad marina le otorga el poder y la fuerza acumulada de cien vidas tras un sacrificio desesperado, Julian empuñará una espada maldita para proteger a una niña indefensa de profecías divinas y reyes despiadados.</p>
<p>Con un dibujo crudo, atmósfera nórdica medieval y batallas a muerte de gran intensidad, es una de las series más prometedoras de la Jump actual.</p>
<p>Encuentra <strong>Centuria en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho a todo Chile.</p>""",

    "look-back": """<p><strong>Look Back</strong> (<em>ルックバック</em>), la conmovedora historia corta creada por <strong>Tatsuki Fujimoto</strong> (autor de <em>Chainsaw Man</em>) en <em>Shōnen Jump+</em> con millones de lecturas en su primer día, es una auténtica carta de amor a la creación artística y a la amistad. La trama sigue a <strong>Ayumu Fujino</strong>, una talentosa estudiante de primaria que publica tiras cómicas en el periódico escolar, quien descubre el virtuoso dibujo de <strong>Kyomoto</strong>, una compañera agorafóbica que no asiste a clases. Al unirse para crear manga juntas, forjarán un vínculo inseparable marcado por el paso del tiempo y giros del destino.</p>
<p>Publicada en un tomo único autoconclusivo de gran impacto emocional, fue adaptada al cine en una galardonada película de animación.</p>
<p>Consigue <strong>Look Back en español</strong> en su edición de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con despacho rápido a todo Chile.</p>""",

    "goodbye-eri": """<p><strong>Goodbye, Eri</strong> (<em>Sayonara Eri</em> / <em>さよなら絵梨</em>), la aclamada obra autoconclusiva concebida por <strong>Tatsuki Fujimoto</strong> para <em>Shōnen Jump+</em>, es una virtuosa exploración sobre el duelo, la memoria y el lenguaje cinematográfico en el manga. Tras el fallecimiento de su madre, a quien filmó en sus últimos días por encargo de ella misma, el joven <strong>Yuta</strong> decide quitarse la vida en el techo de un hospital. Allí conoce a <strong>Eri</strong>, una enigmática cinéfila que lo convence de filmar una nueva película juntos para perfeccionar su estilo, desdibujando la frontera entre la ficción, la fantasía vampírica y la realidad humana.</p>
<p>Con una innovadora composición basada en viñetas de encuadre cinematográfico idéntico, es un cómic de vanguardia reconocido mundialmente.</p>
<p>Compra <strong>Goodbye, Eri en español</strong> por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con entrega garantizada en todo Chile.</p>""",

    "mad": """<p><strong>MAD</strong>, la impactante y visceral serie de terror postapocalíptico y ciencia ficción alienígena creada por <strong>Ryohei Otake</strong> para <em>Shōnen Jump+</em>, sorprendió a la comunidad por su violencia implacable y estilo de dibujo crudo. En un planeta Tierra devastado por una invasión de descomunales criaturas extraterrestres conocidas como invasores, la humanidad sobrevive en ruinas fortificadas y búnkeres subterráneos. Los supervivientes deberán enfrentarse no solo a las aberraciones biológicas de otro mundo, sino también a la locura, el canibalismo y la descomposición moral de los humanos restantes.</p>
<p>Con un ritmo trepidante de persecuciones asfixiantes y horror corporal, es una lectura cargada de adrenalina pura.</p>
<p>Consigue los tomos de <strong>MAD en español</strong> en la edición oficial de <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos a todo Chile.</p>""",

    "jigokuraku-hells-paradise": """<p><strong>Jigokuraku: Hell's Paradise</strong> (<em>地獄楽</em>), la aclamada obra de acción ninja y fantasía sobrenatural de <strong>Yuji Kaku</strong> en <em>Shōnen Jump+</em>, combina artes marciales de época, mitología taoísta y horror corporal. El legendario ninja asesino <strong>Gabimaru «el Vacío»</strong>, condenado a muerte pero incapaz de ser ejecutado por su dominio corporal sobrehumano, recibe una oferta de indulto absoluto de manos de la verdugo Sagiri Asaemon: viajar a la misteriosa isla Shinsenkyo y conseguir el mítico Elixir de la Inmortalidad para el Shogun, compitiendo contra otros criminales condenados y dioses inmortales.</p>
<p>Para continuar la historia tras la primera temporada del anime producido por <strong>MAPPA</strong> (13 episodios), la lectura se retoma desde el <strong>Tomo 05</strong>.</p>
<p>Encuentra la colección completa de <strong>Jigokuraku en español</strong> (13 tomos) por <strong>Editorial Ivrea Argentina</strong> en <strong>Akibara</strong>, con envíos a todo Chile.</p>"""
}
